//! UI translations keyed by the English text: `tr("Play")` returns the current language's
//! version, or the text unchanged. `app/i18n/<locale>.json` is generated by `tools/gen_i18n.py`
//! from Feishin's locale files plus `app/i18n/listen/<locale>.json`.
//! The language is set at start-up and again, live, by onboarding's language step; the settings page
//! only stores the choice for the next start. Each language's table is built once per run and kept
//! (lookups return `&'static str` into it), so switching back and forth costs nothing more.

use std::collections::HashMap;
use std::sync::{Mutex, RwLock};

/// The UI languages: (code, name in its own language).
pub const LANGUAGES: &[(&str, &str)] = &[
    ("en", "English"),
    ("ar", "العربية"),
    ("bn", "বাংলা"),
    ("de", "Deutsch"),
    ("es", "Español"),
    ("fr", "Français"),
    ("hi", "हिन्दी"),
    ("it", "Italiano"),
    ("ko", "한국어"),
    ("nl", "Nederlands"),
    ("pl", "Polski"),
    ("pt", "Português"),
    ("ro", "Română"),
    ("ru", "Русский"),
    ("uk", "Українська"),
    ("ur", "اردو"),
    ("zh-Hans", "简体中文"),
];

/// The language the AI DJ speaks: its own setting (a code), else the app's language.
pub fn dj_language(setting: &str) -> &str {
    match setting.trim() {
        "" => language(),
        code => code,
    }
}

/// The English name of a language code, for the AI DJ's prompt.
pub fn english_name(code: &str) -> &'static str {
    match code {
        "ar" => "Arabic",
        "bn" => "Bengali",
        "de" => "German",
        "es" => "Spanish",
        "fr" => "French",
        "hi" => "Hindi",
        "it" => "Italian",
        "ko" => "Korean",
        "nl" => "Dutch",
        "pl" => "Polish",
        "pt" => "Portuguese",
        "ro" => "Romanian",
        "ru" => "Russian",
        "uk" => "Ukrainian",
        "ur" => "Urdu",
        "zh-Hans" => "Simplified Chinese",
        _ => "English",
    }
}

struct Table {
    code: &'static str,
    map: HashMap<&'static str, &'static str>,
    /// Entries with `{}` holes ("Added {} songs"), matched against built texts in this order: the most
    /// fixed text first, so "Could not delete the playlist: {}" wins over "Could not {} the playlist: {}"
    /// for the same text (the catalog's own order is a HashMap's, different on every start).
    templates: Vec<Template>,
}

struct Template {
    /// The English text split at its holes.
    english: Vec<&'static str>,
    /// The translation split at its holes (at most as many holes; the first ones are filled).
    translated: Vec<&'static str>,
}

impl Template {
    /// The translation of `s` if it is this template with the holes filled in.
    fn apply(&self, s: &str) -> Option<String> {
        let segs = &self.english;
        let (first, last) = (segs.first()?, segs.last()?);
        let mut rest = s.strip_prefix(first)?;
        let end = rest.len().checked_sub(last.len())?;
        if !rest.is_char_boundary(end) || &rest[end..] != *last || segs.len() < 2 {
            return None;
        }
        rest = &rest[..end];
        let mut holes: Vec<&str> = Vec::new();
        for seg in &segs[1..segs.len() - 1] {
            let at = if seg.is_empty() { rest.len().min(1) } else { rest.find(seg)? };
            holes.push(&rest[..at]);
            rest = &rest[at + seg.len()..];
        }
        holes.push(rest);
        if self.translated.len() > holes.len() + 1 {
            return None;
        }
        // A short template ("{} songs") would also hit user text ("Love songs"): its holes
        // must then be numbers.
        let fixed: usize = segs.iter().map(|s| s.len()).sum();
        if fixed < 16 && !holes.iter().all(|h| h.chars().all(|c| c.is_ascii_digit() || " .,:/+-".contains(c)))
        {
            return None;
        }
        let mut out = String::from(self.translated[0]);
        for (hole, seg) in holes.iter().zip(&self.translated[1..]) {
            // "12 songs" inside a longer text is a counted noun of its own.
            match hole.starts_with(|c: char| c.is_ascii_digit()).then(|| lookup(hole)).flatten() {
                Some(t) => out.push_str(&t),
                None => out.push_str(hole),
            }
            out.push_str(seg);
        }
        Some(out)
    }
}

/// The active table. Readers copy the reference out and drop the lock before matching templates
/// ([`Template::apply`] looks up its holes again).
static CURRENT: RwLock<Option<&'static Table>> = RwLock::new(None);

/// Every table built so far, at most one per language for the whole run (see [`table_for`]).
static TABLES: Mutex<Vec<&'static Table>> = Mutex::new(Vec::new());

/// The table of `code`, built and leaked on its first use only: strings handed out by [`tr`] borrow
/// from it for the rest of the run, so it is never freed, and a later switch back reuses it.
fn table_for(code: &'static str) -> &'static Table {
    let mut tables = TABLES.lock().unwrap_or_else(|e| e.into_inner());
    if let Some(table) = tables.iter().find(|t| t.code == code) {
        return table;
    }
    let table: &'static Table = Box::leak(Box::new(build_table(code, source(code))));
    tables.push(table);
    table
}

fn current() -> Option<&'static Table> {
    *CURRENT.read().unwrap_or_else(|e| e.into_inner())
}

/// Development aid: with `LISTEN_I18N_COLLECT=<file>` and a non-English language, every
/// text that has no translation is appended (once) to the file, to find what to translate.
static COLLECT: std::sync::Mutex<Option<(std::path::PathBuf, std::collections::HashSet<String>)>> =
    std::sync::Mutex::new(None);

static COLLECTING: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn collect_miss(s: &str) {
    if !COLLECTING.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut guard = COLLECT.lock().unwrap_or_else(|e| e.into_inner());
    if let Some((path, seen)) = guard.as_mut()
        && s.chars().any(|c| c.is_alphabetic())
        && seen.insert(s.to_string())
    {
        use std::io::Write;
        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
            let _ = writeln!(f, "{}", serde_json::to_string(s).unwrap_or_default());
        }
    }
}

fn source(code: &str) -> Option<&'static str> {
    match code {
        "ar" => Some(include_str!("../i18n/ar.json")),
        "bn" => Some(include_str!("../i18n/bn.json")),
        "de" => Some(include_str!("../i18n/de.json")),
        "es" => Some(include_str!("../i18n/es.json")),
        "fr" => Some(include_str!("../i18n/fr.json")),
        "hi" => Some(include_str!("../i18n/hi.json")),
        "it" => Some(include_str!("../i18n/it.json")),
        "ko" => Some(include_str!("../i18n/ko.json")),
        "nl" => Some(include_str!("../i18n/nl.json")),
        "pl" => Some(include_str!("../i18n/pl.json")),
        "pt" => Some(include_str!("../i18n/pt.json")),
        "ro" => Some(include_str!("../i18n/ro.json")),
        "ru" => Some(include_str!("../i18n/ru.json")),
        "uk" => Some(include_str!("../i18n/uk.json")),
        "ur" => Some(include_str!("../i18n/ur.json")),
        "zh-Hans" => Some(include_str!("../i18n/zh-Hans.json")),
        _ => None,
    }
}

/// `LANG`-style value (`de_DE.UTF-8`, `pt_BR`, `zh_TW`) -> the nearest supported code.
pub fn from_locale(value: &str) -> &'static str {
    let base = value.split(['.', '@']).next().unwrap_or("");
    let norm = base.replace('_', "-");
    let (lang, region) = norm.split_once('-').unwrap_or((norm.as_str(), ""));
    let lang = lang.to_lowercase();
    let found = |code: &str| LANGUAGES.iter().find(|(c, _)| *c == code).map(|(c, _)| *c);
    match (lang.as_str(), region.to_uppercase().as_str()) {
        ("zh", _) => Some("zh-Hans"),
        (l, _) => found(l),
    }
    .unwrap_or("en")
}

/// The code for the `language` setting: `""` follows the system locale.
pub fn resolve(setting: &str) -> &'static str {
    if let Some((code, _)) = LANGUAGES.iter().find(|(c, _)| *c == setting) {
        return code;
    }
    for var in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(v) = std::env::var(var)
            && !v.is_empty()
            && v != "C"
            && v != "POSIX"
        {
            return from_locale(&v);
        }
    }
    "en"
}

/// The table for `code` from its catalog `json`. Patterns with `{}` holes go into `map` as
/// well, so [`trf`] finds their translation however short the fixed text is; `templates`
/// only serves texts that were filled before translation.
fn build_table(code: &'static str, json: Option<&str>) -> Table {
    let mut map = HashMap::new();
    let mut templates = Vec::new();
    if let Some(json) = json
        && let Ok(parsed) = serde_json::from_str::<HashMap<String, String>>(json)
    {
        for (k, v) in parsed {
            // Leaked: a table lives for the whole run (see `table_for`), lookups return `&'static str`.
            let (k, v): (&'static str, &'static str) =
                (Box::leak(k.into_boxed_str()), Box::leak(v.into_boxed_str()));
            if k.contains("{}") && k.matches("{}").count() >= v.matches("{}").count() {
                templates
                    .push(Template { english: k.split("{}").collect(), translated: v.split("{}").collect() });
            }
            map.insert(k, v);
        }
    }
    templates.sort_by_cached_key(|t: &Template| {
        (std::cmp::Reverse(t.english.iter().map(|s| s.len()).sum::<usize>()), t.english.concat())
    });
    Table { code, map, templates }
}

/// Makes `code` (a supported code, see [`resolve`]) the language of [`tr`].
pub fn set_language(code: &str) {
    let code = LANGUAGES.iter().find(|(c, _)| *c == code).map_or("en", |(c, _)| *c);
    let table = table_for(code);
    if let Ok(path) = std::env::var("LISTEN_I18N_COLLECT") {
        *COLLECT.lock().unwrap_or_else(|e| e.into_inner()) = Some((path.into(), Default::default()));
        COLLECTING.store(true, std::sync::atomic::Ordering::Relaxed);
    }
    *CURRENT.write().unwrap_or_else(|e| e.into_inner()) = Some(table);
}

/// The active language code (`en` before [`set_language`]).
pub fn language() -> &'static str {
    current().map_or("en", |t| t.code)
}

fn lookup(s: &str) -> Option<std::borrow::Cow<'static, str>> {
    use std::borrow::Cow;
    let table = current().filter(|t| t.code != "en")?;
    let hit = table
        .map
        .get(s)
        .map(|t| Cow::Borrowed(*t))
        .or_else(|| table.templates.iter().find_map(|t| t.apply(s)).map(Cow::Owned));
    if hit.is_none() {
        collect_miss(s);
    }
    hit
}

/// The translation of the English text `s`; `s` itself when there is none (exact key, no templates).
/// A sentence with holes is built with [`trf`] from its pattern ("Added {} songs"), never by `format!`
/// first: the template rescue in [`tr_cow`] only fills holes that are numbers unless the pattern has at
/// least 16 fixed bytes, and it never translates a hole's words.
pub fn tr(s: &str) -> &str {
    match current() {
        Some(t) if t.code != "en" => t.map.get(s).copied().unwrap_or(s),
        _ => s,
    }
}

/// [`tr`] for the owned/borrowed strings iced text takes (what `ui::label` uses). A text that is not a
/// key is matched against the `{}` templates as a rescue for counts ("12 songs"); a template with fewer
/// than 16 fixed bytes only matches when every hole is a number, so "AI DJ · Nova" stays English. Build
/// such text with [`trf`].
pub fn tr_cow(s: std::borrow::Cow<'_, str>) -> std::borrow::Cow<'_, str> {
    match lookup(&s) {
        Some(t) => t,
        None => s,
    }
}

/// [`tr`] with `{}` placeholders filled in order: `trf("Added {} songs", &[&n])`.
pub fn trf(pattern: &str, args: &[&dyn std::fmt::Display]) -> String {
    fill(tr(pattern), args)
}

/// `pattern` with its `{}` holes filled in order (holes without an argument stay empty).
fn fill(pattern: &str, args: &[&dyn std::fmt::Display]) -> String {
    let mut out = String::new();
    let mut args = args.iter();
    let mut rest = pattern;
    while let Some(i) = rest.find("{}") {
        out.push_str(&rest[..i]);
        if let Some(a) = args.next() {
            out.push_str(&a.to_string());
        }
        rest = &rest[i + 2..];
    }
    out.push_str(rest);
    out
}

/// "Why this song?": the reason of a DJ's pick, translated.
pub fn why(why: &listen_core::queue::Why) -> String {
    let (pattern, args) = why.template(listen_core::history::now_secs());
    let args: Vec<&dyn std::fmt::Display> = args.iter().map(|a| a as &dyn std::fmt::Display).collect();
    trf(pattern, &args)
}

/// Tests: the `code` translation of `s` without switching the app's language.
#[cfg(test)]
pub(crate) fn translate_in(code: &str, s: &str) -> Option<String> {
    let code = LANGUAGES.iter().find(|(c, _)| *c == code).map_or("en", |(c, _)| *c);
    build_table(code, source(code)).map.get(s).map(|t| t.to_string())
}

/// Tests: every `.rs` file under `app/src/<dir>` as (repo-relative path, text), for checks over the
/// sources (e.g. that every counted noun has catalog keys).
#[cfg(test)]
pub(crate) fn rust_sources(dir: &str) -> Vec<(String, String)> {
    fn walk(path: &std::path::Path, out: &mut Vec<(String, String)>) {
        let Ok(entries) = std::fs::read_dir(path) else { return };
        for entry in entries.flatten() {
            let p = entry.path();
            if p.is_dir() {
                walk(&p, out);
            } else if p.extension().is_some_and(|e| e == "rs")
                && let Ok(text) = std::fs::read_to_string(&p)
            {
                let rel = p.strip_prefix(env!("CARGO_MANIFEST_DIR")).unwrap_or(&p).display().to_string();
                out.push((rel, text));
            }
        }
    }
    let mut out = Vec::new();
    walk(&std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join(dir), &mut out);
    assert!(!out.is_empty(), "no sources under app/src/{dir}");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `gen_i18n.py` copies every entry of `app/i18n/listen/<code>.json` into `app/i18n/<code>.json`; a
    /// string added by hand to both files must match, or the next run of the script changes it.
    #[test]
    fn merged_tables_carry_every_listen_entry() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("i18n");
        let read = |path: std::path::PathBuf| -> std::collections::BTreeMap<String, String> {
            let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
        };
        for (code, _) in LANGUAGES.iter().filter(|(code, _)| *code != "en") {
            let merged = read(dir.join(format!("{code}.json")));
            for (key, value) in read(dir.join("listen").join(format!("{code}.json"))) {
                assert_eq!(
                    merged.get(&key),
                    Some(&value),
                    "{code}: {key:?} differs from app/i18n/listen/{code}.json"
                );
            }
        }
    }

    /// `ui::plural(n, "word")` looks up "1 word" / "{} words": a noun without both keys shows its
    /// count in English, and a joined line ("4 albums · 52 tracks") can never be translated later.
    #[test]
    fn every_plural_noun_has_german_keys() {
        let de = build_table("de", source("de"));
        let mut missing = Vec::new();
        for (path, src) in rust_sources("").into_iter().filter(|(p, _)| !p.ends_with("i18n.rs")) {
            for (at, _) in src.match_indices("plural(") {
                if src[..at].ends_with("fn ") {
                    continue;
                }
                let call = &src[at..src.len().min(at + 160)];
                let Some(q) = call.find(", \"") else { continue };
                let rest = &call[q + 3..];
                let Some(end) = rest.find('"') else { continue };
                let word = &rest[..end];
                for key in [format!("1 {word}"), format!("{{}} {word}s")] {
                    if !de.map.contains_key(key.as_str()) {
                        missing.push(format!("{path}: {key}"));
                    }
                }
            }
        }
        assert!(missing.is_empty(), "add to app/i18n/listen/de.json and app/i18n/de.json: {missing:#?}");
    }

    /// Onboarding switches the language live on every click: each language is built once per run.
    #[test]
    fn each_language_table_is_built_once_per_run() {
        let de = table_for("de");
        let fr = table_for("fr");
        assert!(!std::ptr::eq(de, fr));
        assert!(std::ptr::eq(table_for("de"), de), "switching back built a second German table");
        assert!(std::ptr::eq(table_for("fr"), fr));
        let tables = TABLES.lock().unwrap_or_else(|e| e.into_inner());
        assert_eq!(tables.iter().filter(|t| t.code == "de").count(), 1);
    }

    #[test]
    fn the_most_specific_template_wins() {
        let json =
            r#"{"Could not {} the playlist: {}": "A {} B {}", "Could not delete the playlist: {}": "C {}"}"#;
        let table = build_table("xx", Some(json));
        let hit = table.templates.iter().find_map(|t| t.apply("Could not delete the playlist: gone"));
        assert_eq!(hit.as_deref(), Some("C gone"));
    }

    #[test]
    fn locale_names_map_to_codes() {
        assert_eq!(from_locale("de_DE.UTF-8"), "de");
        assert_eq!(from_locale("pt_BR.UTF-8"), "pt");
        assert_eq!(from_locale("pt_PT"), "pt");
        assert_eq!(from_locale("zh_CN"), "zh-Hans");
        assert_eq!(from_locale("ja_JP.UTF-8"), "en");
        assert_eq!(from_locale("xx_YY"), "en");
        assert_eq!(from_locale("C"), "en");
        assert_eq!(resolve("fr"), "fr");
    }

    #[test]
    fn every_language_has_a_table_that_parses() {
        assert_eq!(LANGUAGES.len(), 17);
        for (code, _) in LANGUAGES.iter().filter(|(c, _)| *c != "en") {
            let json = source(code).unwrap_or_else(|| panic!("{code} missing"));
            let map: HashMap<String, String> = serde_json::from_str(json).unwrap();
            assert!(map.len() > 1000, "{code}: {}", map.len());
        }
    }

    #[test]
    fn placeholders_fill_in_order() {
        // English (and any text without a table entry) passes through.
        assert_eq!(trf("{} of {}", &[&1, &2]), "1 of 2");
    }

    #[test]
    fn short_patterns_translate_with_text_holes() {
        // "Playing on {}: {}" has 13 fixed characters: too short for the template rescue of
        // filled texts, so the pattern itself must be looked up before filling.
        let de = build_table("de", source("de"));
        let pattern = de.map.get("Playing on {}: {}").copied().unwrap();
        assert_eq!(fill(pattern, &[&"QA Handy", &"LOVE · StayC"]), "Läuft auf QA Handy: LOVE · StayC");
        let cast = de.map.get("Casting to {}").copied().unwrap();
        assert_eq!(fill(cast, &[&"Wohnzimmer"]), "Übertragung auf Wohnzimmer");
        // Filled texts still translate through the templates when the holes are numbers.
        assert!(de.templates.iter().any(|t| t.english == ["Playing on ", ": ", ""]));
    }

    /// A short pattern with a text hole only translates through `trf`: the filled text no longer
    /// matches a template, so `format!` + `ui::label` shows it in English.
    #[test]
    fn sentences_with_text_holes_translate_only_through_trf() {
        let de = build_table("de", source("de"));
        let filled = "AI DJ · Nova";
        assert!(!de.map.contains_key(filled));
        assert!(de.templates.iter().all(|t| t.apply(filled).is_none()), "the template rescue changed");
        let pattern = de.map.get("AI DJ · {}").copied().unwrap();
        assert_eq!(fill(pattern, &[&"Nova"]), "KI-DJ · Nova");
        // Numbers still go through the template rescue.
        assert!(de.templates.iter().any(|t| t.apply("12 songs").is_some()));
    }
}
